#define MAXN 200005

static char s[MAXN];

static inline int max2(int a, int b) { return a > b ? a : b; }
static inline int min2(int a, int b) { return a < b ? a : b; }

int main(void) {
    if (scanf("%200000s", s) != 1) return 0;
    int n = (int)strlen(s);

    // Binary search the minimum possible answer K.
    // Map: '0' -> +1, '1' -> -1, '?' -> choose either.
    // We need all prefix sums p[i] to stay within some interval [L, L+K],
    // equivalently max(prefix)-min(prefix) <= K.
    // Since p[0]=0, it suffices to check whether there exists a path of
    // prefix sums within [-K, K] with steps:
    //   '0': +1, '1': -1, '?': +/-1
    // This is enough because any such path has width <= K.

    int lo = 0, hi = n;
    while (lo < hi) {
        int k = (lo + hi) / 2;

        // dp interval of reachable prefix sums after processing i chars,
        // intersected with [-k, k]. Reachable set remains an interval
        // because transitions are by shifting intervals by +/-1 and unioning.
        int L = 0, R = 0; // reachable sums after 0 chars

        int ok = 1;
        for (int i = 0; i < n; ++i) {
            int nL, nR;
            if (s[i] == '0') {
                nL = L + 1;
                nR = R + 1;
            } else if (s[i] == '1') {
                nL = L - 1;
                nR = R - 1;
            } else {
                // union of [L-1, R-1] and [L+1, R+1] -> [L-1, R+1]
                nL = L - 1;
                nR = R + 1;
            }

            // intersect with [-k, k]
            L = max2(nL, -k);
            R = min2(nR,  k);

            if (L > R) {
                ok = 0;
                break;
            }
        }

        if (ok) hi = k;
        else lo = k + 1;
    }

    printf("%d\n", lo);
    return 0;
}

