    // window must contain [0, current], so window_lo in [current-k, 0], window_hi in [0, current+k]
    // simplify: just track lo,hi clipped to window of size k containing 0
    int wlo = -k, whi = k; // window can be anywhere, but must contain 0
    // Actually: window must contain all past values. Past min >= wlo, past max <= whi, whi-wlo=k
    // Track feasible [lo,hi] directly, ensure hi-lo<=k always, and 0 in initial
    for(int i=0;i<n;i++){
        int d = (s[i]=='1')?1:(s[i]=='0'?-1:0);
        if(s[i]=='?'){lo--;hi++;}
        else{lo+=d;hi+=d;}
        // clip: hi-lo <= k
