import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static boolean can(char[] s, int K) {
        int n = s.length;

        // Prefix sums P[i], with P[0] = 0 and step +/-1.
        // We need max(P)-min(P) <= K.
        // DP over possible current prefix sums, restricted to a sliding interval of width K.
        // Equivalent condition: there exists some shift t such that all P[i] in [t, t+K].
        // Since P[0]=0, necessarily t in [-K, 0].
        // DP state: possible current prefix values after processing i chars.

        int offset = n + K + 5;
        int size = 2 * offset + 1;

        BitSet cur = new BitSet(size);
        cur.set(offset); // prefix sum 0

        for (char c : s) {
            BitSet next = new BitSet(size);
            if (c == '0' || c == '?') {
                // 0 contributes +1 to (#0 - #1)
                for (int p = cur.nextSetBit(0); p >= 0; p = cur.nextSetBit(p + 1)) {
                    next.set(p + 1);
                }
            }
            if (c == '1' || c == '?') {
                // 1 contributes -1
                for (int p = cur.nextSetBit(0); p >= 0; p = cur.nextSetBit(p + 1)) {
                    next.set(p - 1);
                }
            }
            cur = next;
            if (cur.isEmpty()) return false;
        }

        // The above only tracks reachable final sums, not the width constraint during the path.
        // Need proper DP with bounded range throughout.
        // We instead test whether there exists interval [L, L+K] containing all prefix sums.
        // Since 0 must lie inside it, L in [-K, 0]. For each L, do path DP constrained inside interval.

        for (int L = -K; L <= 0; L++) {
            int R = L + K;
            BitSet dp = new BitSet(K + 1);
            dp.set(-L); // prefix sum 0 mapped to 0-L

            boolean ok = true;
            for (char c : s) {
                BitSet ndp = new BitSet(K + 1);
                if (c == '0' || c == '?') {
                    for (int p = dp.nextSetBit(0); p >= 0; p = dp.nextSetBit(p + 1)) {
                        if (p + 1 <= K) ndp.set(p + 1);
                    }
                }
                if (c == '1' || c == '?') {
                    for (int p = dp.nextSetBit(0); p >= 0; p = dp.nextSetBit(p + 1)) {
                        if (p - 1 >= 0) ndp.set(p - 1);
                    }
                }
                dp = ndp;
                if (dp.isEmpty()) {
                    ok = false;
                    break;
                }
            }
            if (ok) return true;
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String str = fs.next();
        if (str == null) return;
        char[] s = str.toCharArray();
        int n = s.length;

        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (can(s, mid)) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

