#include <bits/stdc++.h>
using namespace std;

bool feasible(const string& s, int k) {
    int lo = 0, hi = 0; // range of possible "f" values (current P - running min)
    for (char c : s) {
        int nlo, nhi;
        auto apply = [&](int delta, int& alo, int& ahi, bool first) {
            int l = lo + delta, h = hi + delta;
            // if goes below 0, clamp to 0 (window shifts up)
            if (h < 0) { if(first){alo=ahi=-1;} return; }
            l = max(l, 0);
            if (l > k) { if(first){alo=ahi=-1;} return; }
            h = min(h, k);
            if (first) { alo = l; ahi = h; }
            else { alo = min(alo, l); ahi = max(ahi, h); }
        };
        if (c == '1') { apply(1, nlo, nhi, true); }
        else if (c == '0') { apply(-1, nlo, nhi, true); }
        else { apply(1, nlo, nhi, true); apply(-1, nlo, nhi, false); }
        if (nlo == -1) return false;
        lo = nlo; hi = nhi;
    }
    return true;
}

