int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int n = (int)s.size();

    auto feasible = [&](int K) -> bool {
        // Prefix sums p[i], p[0]=0, p[i]-p[i-1] in {-1,+1}
        // For fixed K, need all prefix sums within width K:
        // max(p)-min(p) <= K  <=>  there exists interval [L, L+K] containing all p[i].
        // DP over possible prefix values x in [0..K], representing p[i] = L + x for some unknown L.
        vector<char> dp(K + 1, 0), ndp(K + 1, 0);

        // p[0] must be inside [L, L+K], so x = -L can be any value in [0..K]
        fill(dp.begin(), dp.end(), 1);

        for (char c : s) {
            fill(ndp.begin(), ndp.end(), 0);
            if (c == '0' || c == '?') {
                // 0 contributes +1 to (#0-#1)
                for (int x = 0; x < K; ++x) {
                    if (dp[x]) ndp[x + 1] = 1;
                }
            }
            if (c == '1' || c == '?') {
                // 1 contributes -1
                for (int x = 1; x <= K; ++x) {
                    if (dp[x]) ndp[x - 1] = 1;
                }
            }
            dp.swap(ndp);

            bool any = false;
            for (char v : dp) if (v) { any = true; break; }
            if (!any) return false;
        }
        return true;
    };

    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (feasible(mid)) hi = mid;
        else lo = mid + 1;
    }

    cout << lo << '\n';
    return 0;
}

